import {miniTime} from './rebuild-views-e14b41d62339.mjs';
import {rangeStatistics} from './rebuild-model-e14b41d62339.mjs';
import {readAttachment,exportAttachment} from './attachments-e14b41d62339.mjs';
import {applyAppearance} from './appearance-e14b41d62339.mjs';
import * as D from './domain-e14b41d62339.mjs';
export function diaryEntries(state){
 return [...state.moments.map(m=>({...m,kind:'moment'})),...Object.entries(state.dailyNotes).filter(([,v])=>v.text?.trim()).map(([date,v])=>({id:(state.moments.some(m=>m.id==='daily:'+date)?'legacy-daily:':'daily:')+date,kind:'daily',date,at:D.dayStart(date,state.timeZone)+12*3600000,title:'当天感受',text:v.text,photos:[],sessionId:null,updatedAt:v.updatedAt??0}))].sort((a,b)=>b.at-a.at);
}
export const entryFingerprint=entry=>entry?D.checksum(JSON.stringify(entry)):null;
export function commitDiary(state,draft){
 const out=D.copy(state),original=diaryEntries(out).find(m=>m.id===draft.targetId);
 if(entryFingerprint(original)!==draft.originalHash)throw new Error('这篇日记已在其他页面变化，草稿保留，请重新核对');
 if(!draft.text.trim()&&!draft.title.trim()&&!draft.photos.length&&!draft.attachments?.length&&!draft.timeSummary?.rows?.length)throw new Error('还没有内容，返回即可留白');
 const item={id:draft.targetId??draft.entryId??draft.id,at:draft.at,title:draft.title||'',text:draft.text,photos:D.copy(draft.photos),attachments:D.copy(draft.attachments??[]),entryKind:draft.entryKind??'daily',includeTime:!!draft.includeTime,timeSummary:draft.timeSummary??null,sessionId:draft.sessionId||null,createdAt:original?.createdAt??Date.now(),updatedAt:Date.now()};
 if(original?.kind==='daily')delete out.dailyNotes[original.date];
 const index=out.moments.findIndex(m=>m.id===item.id);if(index<0)out.moments.push(item);else out.moments[index]={...out.moments[index],...item};
 return D.validateState(out);
}
export function diaryCollection(state,ui,{e,dateControl,momentContent}){
 const entries=diaryEntries(state).filter(m=>!ui.rangeStart||(D.dateKey(m.at,state.timeZone)>=ui.rangeStart&&D.dateKey(m.at,state.timeZone)<=ui.rangeEnd)),groups=new Map();
 for(const m of entries){const date=D.dateKey(m.at,state.timeZone);if(!groups.has(date))groups.set(date,[]);groups.get(date).push(m);}
 return `<section class="heading"><div><span class="eyebrow">WORDS & MOMENTS</span><h1>把此刻，留给以后。</h1><p>你写下的文字与照片，按日收藏。没有内容的日子自然留白。</p></div><button type="button" class="primary" data-action="new-moment">＋ 写一篇</button></section><details class="card section-fold" id="memory-filter" data-preserve><summary>日期筛选与范围导出${ui.rangeStart?' · '+ui.rangeStart+'—'+ui.rangeEnd:''}</summary><form id="memory-range" class="range-form"><label>开始日期<input type="date" name="start" value="${ui.rangeStart||ui.date}" required></label><label>结束日期<input type="date" name="end" value="${ui.rangeEnd||ui.date}" required></label><button class="secondary">按日期筛选</button><button type="button" class="text-button" data-action="reset-range">显示全部</button><button type="button" class="text-button" data-action="export-range">按范围导出</button></form></details>${(ui.drafts||[]).filter(d=>d.kind==='diary').length?`<section class="card"><h2>草稿</h2><div class="draft-list">${ui.drafts.filter(d=>d.kind==='diary').map(d=>`<button type="button" class="secondary" data-action="resume-diary" data-id="${e(d.id)}">${e(d.title||d.text?.slice(0,24)||'未写完的日记')} · 继续编辑</button>`).join('')}</div></section>`:''}${[...groups].map(([date,rows])=>`<section class="card diary-day"><div class="section-title"><h2>${date}</h2><button type="button" class="text-button" data-action="day-records" data-id="${date}">查看当天记录</button></div>${rows.map(m=>`<article class="diary-entry diary-preview" id="diary-${e(m.id)}"><button type="button" class="row-title" data-action="moment" data-id="${e(m.id)}">${e(m.title||'日记')}</button>${m.sessionId?'<span class="tag">引用活动</span>':''}${momentContent({...m,text:m.text.length>140?m.text.slice(0,140)+'…':m.text,photos:m.photos.slice(0,3)})}${m.photos.length>3?`<p class="muted">共${m.photos.length}张照片 · 打开日记查看全部</p>`:''}</article>`).join('')}</section>`).join('')||'<section class="card empty"><h2>还没有写下内容</h2><p>想写时再来，文字和图片都可以。</p></section>'}`;
}
export function createDiaryEditor({getState,getRepo,app,render,save,toast,closeModal,e}){
 let draft=null,queue=Promise.resolve(),timer=null,photoBusy=false,saving=false,lastError=null,epoch=0,resizeObserver=null;
 const status=text=>{const el=app.querySelector('#diary-status');if(el)el.textContent=text;};
 function capture(){if(!draft)return;const form=app.querySelector('#diary-form');if(!form)return;const f=new FormData(form);draft.title=String(f.get('title')||'');draft.text=String(f.get('text')||'');draft.atInput=f.get('at');draft.sessionId=f.get('sessionId')||null;draft.entryKind=f.get('entryKind')||draft.entryKind||'daily';draft.includeTime=f.has('includeTime')&&draft.entryKind==='daily';draft.updatedAt=Date.now();}
 function flush(photosChanged=false){clearTimeout(timer);capture();if(!draft)return queue;if(!draft.targetId&&!draft.text.trim()&&!draft.title.trim()&&!draft.photos.length&&!draft.attachments.length)return queue;const snapshot=D.copy(draft);status('');queue=queue.catch(()=>{}).then(()=>getRepo().saveDraft(snapshot,{photosChanged})).then(()=>{lastError=null;status('');}).catch(error=>{lastError=error;status('草稿未保存：'+error.message);});return queue;}
 function schedule(){capture();status('');clearTimeout(timer);timer=setTimeout(()=>flush(),350);}
 function photos(){const el=app.querySelector('#diary-photos');if(!el||!draft)return;el.innerHTML=draft.photos.map((p,i)=>`<figure><button type="button" data-diary-photo="${i}" aria-label="查看 ${e(p.name)}"><img src="${e(p.data)}" alt="${e(p.name)}"></button><button type="button" class="text-button" data-diary-remove="${i}">移除图片</button></figure>`).join('');}
 function files(){const el=app.querySelector('#diary-files');if(!el||!draft)return;el.innerHTML=draft.attachments.map((f,i)=>`<div><button type="button" class="text-button" data-file-download="${i}">${e(f.name)} <small>${(f.size/1000).toFixed(1)}KB · 下载原件</small></button><button type="button" class="text-button" data-file-remove="${i}" aria-label="移除 ${e(f.name)}">移除</button></div>`).join('');}
 function summary(){const el=app.querySelector('#diary-time-summary');if(!el||!draft)return;try{const s=getState(),at=D.parseLocal(draft.atInput,s.timeZone);el.innerHTML=draft.entryKind==='daily'&&draft.includeTime?miniTime(s,D.dateKey(at,s.timeZone)):'';}catch{el.innerHTML='';}}
 async function open(targetId=null,sessionId=null,resumeId=null,entryKind='daily'){
  await closeModal();epoch++;const state=getState(),original=diaryEntries(state).find(m=>m.id===targetId);
  const all=await getRepo().listDrafts(),existing=all.find(d=>d.kind==='diary'&&(resumeId?d.id===resumeId:targetId&&d.targetId===targetId));
  draft=existing??{id:D.uid(),entryId:D.uid(),kind:'diary',targetId:original?.id??null,originalHash:entryFingerprint(original),operationId:D.uid(),at:original?.at??Date.now(),title:original?.title??'',text:original?.text??'',photos:D.copy(original?.photos??[]),attachments:D.copy(original?.attachments??[]),entryKind:original?.entryKind??entryKind,includeTime:original?.includeTime??(entryKind==='daily'&&state.rebuild.includeDiaryTime),sessionId:original?.sessionId??sessionId,updatedAt:Date.now()};
  draft.title??='';draft.text??='';draft.photos??=[];globalThis.NGNLNative?.setEditorOpen?.(true);draft.attachments??=[];draft.entryKind??='daily';draft.includeTime??=draft.entryKind==='daily'&&state.rebuild.includeDiaryTime;draft.atInput=draft.atInput||D.localInput(draft.at,state.timeZone,true);lastError=null;
  app.innerHTML=`<main id="main" class="diary-editor"><form id="diary-form"><header class="diary-toolbar"><button type="button" class="secondary" id="diary-back">‹ 返回</button><button class="primary" id="diary-save">保存</button></header><p id="diary-status" class="quiet-note" role="status"></p><div class="r-diary-heading"><label>标题（可选）<textarea name="title" rows="1" maxlength="100" placeholder="标题">${e(draft.title)}</textarea></label><div class="r-diary-summary" id="diary-time-summary"></div></div><label class="diary-writing-label"><span class="sr-only">日记正文</span><textarea name="text" maxlength="200000" placeholder="">${e(draft.text)}</textarea></label><div class="r-diary-add"><label class="secondary file-button">＋ 添加图片<input type="file" name="photos" accept="image/*" multiple hidden></label><label class="secondary file-button">＋ 添加文件<input type="file" name="attachments" multiple hidden></label></div><details class="r-file-help"><summary>文件说明</summary><small class="r-file-hint">文件每个≤10MB，每篇≤20个；保存原件供下载。</small></details><div id="diary-photos" class="diary-photos"></div><div id="diary-files" class="r-file-list"></div><details><summary>日期、类型与时间摘要</summary><label>保存为<select name="entryKind"><option value="daily" ${draft.entryKind==='daily'?'selected':''}>每日闪回</option><option value="note" ${draft.entryKind==='note'?'selected':''}>碎念</option></select></label><label class="check"><input type="checkbox" name="includeTime" ${draft.includeTime?'checked':''}>附入当天时间概览与时间线</label><label>日期与时间<input type="datetime-local" name="at" step="1" value="${e(draft.atInput)}" required></label><label>活动<select name="sessionId"><option value="">独立日记</option>${D.confirmedSessions(state).map(s=>`<option value="${e(s.id)}" ${draft.sessionId===s.id?'selected':''}>${D.dateKey(s.start,state.timeZone)} ${e(s.name)}</option>`).join('')}${draft.sessionId&&!D.confirmedSessions(state).some(s=>s.id===draft.sessionId)?`<option value="${e(draft.sessionId)}" selected>保留原活动引用</option>`:''}</select></label></details><p id="diary-error" class="form-error" role="alert" hidden></p><button type="button" class="text-button" id="diary-discard">放弃这份编辑草稿</button><div id="diary-discard-confirm" hidden><p>只删除本地草稿，原有正式日记保留。</p><button type="button" class="danger-button" id="diary-discard-yes">确认放弃草稿</button><button type="button" class="secondary" id="diary-discard-no">继续写</button></div></form></main>`;
  applyAppearance(state,'diaryEditor',await getRepo().listAssets());
  photos();files();summary();const form=app.querySelector('#diary-form'),error=err=>{const el=app.querySelector('#diary-error');if(el){el.hidden=false;el.textContent=err.message;}};
  const resizeWriting=()=>{for(const name of ['title','text']){const el=form.elements[name];el.style.height='auto';el.style.height=Math.min(el.scrollHeight+2,name==='title'?1000:Math.max(120,innerHeight*.65))+'px';}};
  resizeObserver?.disconnect();let lastWidth=0;resizeObserver=new ResizeObserver(entries=>{const width=entries[0]?.contentRect.width;if(width!==lastWidth){lastWidth=width;resizeWriting();}});resizeObserver.observe(form);resizeWriting();
  form.addEventListener('input',()=>{resizeWriting();schedule();});form.addEventListener('change',event=>{if(!['photos','attachments'].includes(event.target.name))schedule();if(['at','includeTime','entryKind'].includes(event.target.name))summary();});
  form.querySelector('#diary-back').onclick=()=>leave().catch(error);
  form.querySelector('#diary-discard').onclick=()=>form.querySelector('#diary-discard-confirm').hidden=false;
  form.querySelector('#diary-discard-no').onclick=()=>form.querySelector('#diary-discard-confirm').hidden=true;
  form.querySelector('#diary-discard-yes').onclick=async()=>{if(photoBusy||saving)return;clearTimeout(timer);await queue;const id=draft.id;try{await getRepo().deleteDraft(id);draft=null;epoch++;resizeObserver?.disconnect();globalThis.NGNLNative?.setEditorOpen?.(false);await render();}catch(err){error(err);}};
  form.onsubmit=async event=>{event.preventDefault();if(photoBusy||saving)return;saving=true;form.querySelector('#diary-save').disabled=true;form.querySelector('[name=photos]').disabled=true;try{await flush();if(lastError)throw lastError;const snapshot=D.copy(draft);snapshot.at=D.parseLocal(snapshot.atInput,getState().timeZone);if(snapshot.includeTime&&snapshot.entryKind==='daily'){const date=D.dateKey(snapshot.at,getState().timeZone),stat=rangeStatistics(getState(),date,date);snapshot.timeSummary={date,timeZone:getState().timeZone,ruleVersion:1,sourceRevision:getState().revision,rows:stat.rows.filter(r=>!r.live).map(r=>({id:r.id,start:r.start,end:r.end,activityId:r.activityId}))};}else snapshot.timeSummary=null;await save(s=>commitDiary(s,snapshot),{operationId:snapshot.operationId,clearDraftId:snapshot.id});draft=null;epoch++;resizeObserver?.disconnect();globalThis.NGNLNative?.setEditorOpen?.(false);await render();toast('已保存');}catch(err){error(err);}finally{saving=false;if(form.isConnected){form.querySelector('#diary-save').disabled=false;form.querySelector('[name=photos]').disabled=false;}}};
  form.querySelector('[name="photos"]').onchange=async event=>{
   if(photoBusy||saving)return;const token=epoch,files=[...event.target.files];photoBusy=true;let photoError=null;event.target.disabled=true;form.querySelector('#diary-save').disabled=true;status('正在读取图片…');
   try{if(draft.photos.length+files.length>30)throw new Error('每篇最多30张图片');const added=[];for(const file of files){if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type))throw new Error('请选择JPEG、PNG、WebP或GIF图片');if(file.size>15000000)throw new Error('单张图片不能超过15MB');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('图片读取失败'));reader.readAsDataURL(file);});added.push({id:D.uid(),name:file.name.slice(0,200),type:file.type,data});}if(token!==epoch||!draft)return;draft.photos.push(...added);photos();await flush(true);}
   catch(err){photoError=err;error(err);}finally{photoBusy=false;event.target.value='';event.target.disabled=false;if(form.isConnected){form.querySelector('#diary-save').disabled=false;if(photoError)status('图片未添加：'+photoError.message);else if(!lastError)status('');}}
  };
  form.querySelector('#diary-photos').onclick=async event=>{const b=event.target.closest('[data-diary-remove]'),view=event.target.closest('[data-diary-photo]');if(b&&!photoBusy&&!saving){draft.photos.splice(Number(b.dataset.diaryRemove),1);photos();await flush(true);}if(view){const photo=draft.photos[Number(view.dataset.diaryPhoto)],overlay=document.createElement('dialog');overlay.className='photo-viewer';const img=document.createElement('img');img.src=photo.data;img.alt=photo.name;overlay.append(img);const close=document.createElement('button');close.textContent='关闭大图';close.className='secondary';close.onclick=()=>overlay.close();overlay.append(close);overlay.onclose=()=>overlay.remove();document.body.append(overlay);overlay.showModal();}};
  form.querySelector('[name=attachments]').onchange=async event=>{if(photoBusy||saving)return;photoBusy=true;form.querySelector('#diary-save').disabled=true;try{const selected=[...event.target.files];if(draft.attachments.length+selected.length>20)throw Error('每篇最多20个文件');const added=[];for(const file of selected)added.push(await readAttachment(file));draft.attachments.push(...added);files();await flush(true);}catch(err){error(err);}finally{photoBusy=false;event.target.value='';form.querySelector('#diary-save').disabled=false;}};
  form.querySelector('#diary-files').onclick=async event=>{const remove=event.target.closest('[data-file-remove]'),download=event.target.closest('[data-file-download]');try{if(remove&&!photoBusy&&!saving){draft.attachments.splice(Number(remove.dataset.fileRemove),1);files();await flush(true);}if(download){const result=await exportAttachment(draft.attachments[Number(download.dataset.fileDownload)]);if(result.native&&!result.saved)status('已取消导出，附件仍保留');}}catch(err){error(err);}};
  if(existing||original)await flush(true);
 }
 async function leave(){if(!draft)return;if(photoBusy)throw new Error('图片仍在读取，请稍候再返回');if(saving)throw new Error('正在保存，请稍候');await flush();if(lastError)throw lastError;draft=null;epoch++;resizeObserver?.disconnect();globalThis.NGNLNative?.setEditorOpen?.(false);await render();}
 return {open,leave,flush,get active(){return !!draft;}};
}
